// evita repetir la misma alerta mientras la condicion siga igual
const memoria = $getWorkflowStaticData('global');
const actual = $input.first().json;
const firma = actual.alerta_h3 ? actual.detalle_hallazgos : 'SIN_CAMBIOS';
const nueva = actual.alerta_h3 && firma !== memoria.ultimoH3;
memoria.ultimoH3 = firma;
return [{ json: { ...actual, alerta_h3: nueva } }];
